  "privWhat1": "Коли ви створюєте обліковий запис, ми використовуємо вашу електронну адресу, ідентифікатор облікового запису, дані автентифікації за паролем і статус підтвердження, щоб надавати й захищати ваш обліковий запис. Паролі обробляє постачальник автентифікації у вигляді надійних хешів; Cook не зберігає паролі в читабельному вигляді. Ми зберігаємо планування кухні, вибрану мову, тему й одиниці виміру, щоб відновлювати ваші налаштування на всіх пристроях. Для облікового запису потрібні електронна адреса й пароль; рецепти можна переглядати й без нього.",
  "privWhat2": "Обробка облікового запису й налаштувань потрібна, щоб надавати запитану вами послугу облікового запису (пункт (b) частини 1 статті 6 GDPR). Обмежені записи для безпеки та запобігання зловживанням можуть оброблятися на підставі законних інтересів (пункт (f) частини 1 статті 6) у необхідному обсязі та після зважування інтересів. Листи для підтвердження й скидання пароля — це службові повідомлення, а не маркетинг. Функція облікового запису не додає реклами чи аналітики.",
  "privStorage1": "Cook використовує sessionStorage, щоб переносити вашу кухню, хід приготування й вибір між сторінками в одній вкладці. Коли ви ввійшли, там також зберігається ваш сеанс входу. Браузер зазвичай очищає ці дані після завершення сеансу вкладки, але відновлення сеансів у браузері може їх зберегти. Вихід з облікового запису очищає дані Cook у вкладці. Закриття повідомлення про сховище запам’ятовується лише в цій вкладці. Власні скрипти Cook не встановлюють файли cookie. Ваші постачальники хостингу чи послуг можуть виконувати власну обробку з метою безпеки, яку потрібно задокументувати до запуску.",
  "privStorage2": "Кнопки «OK» і закриття повідомлення про сховище лише закривають повідомлення. Вони не дозволяють аналітику, рекламу чи інше необов’язкове відстеження. Будь-яке майбутнє необов’язкове зберігання потребуватиме окремого вибору до його початку, з такою ж простою відмовою та відкликанням.",
  "privOther1": "Поточна голосова функція списку рецептів запитує в country.is приблизну країну за вашою IP-адресою, щоб вибрати мову розпізнавання мовлення. Якщо ви користуєтеся розпізнаванням через мікрофон, браузер може надсилати звук своєму постачальнику розпізнавання мовлення. Інгредієнти також можна ввести вручну. Цих постачальників, їхні політики та правову підставу цих функцій потрібно перевірити до публічного запуску.",
  "privProviders1": "Запланований постачальник облікових записів: Supabase (керований PostgreSQL і автентифікація) з вибраним регіоном бази даних у ЄС. Постачальник ел. пошти: [постачальник]. Хостинг сайту: [постачальник]. Оператор має підтвердити фактичних постачальників, договори про обробку, субобробників, місця зберігання журналів і будь-яку передачу даних за межі ЄЕЗ. Регіон бази даних у ЄС сам по собі не виключає міжнародної передачі. За потреби вкажіть відповідне рішення про адекватність або договірні гарантії та спосіб отримати їх копію.",
  "privRetention1": "Налаштування облікового запису зберігаються, поки ваш обліковий запис активний. Ви можете попросити про видалення через указаний вище контакт із питань конфіденційності. До запуску оператор має визначити порядок відповіді на запити про видалення, строк дії непідтверджених облікових записів і строки зберігання журналів безпеки та резервних копій. Видалені дані можуть залишатися в резервних копіях з обмеженим доступом до кінця задокументованого строку зберігання.",
  "privRights1": "Залежно від застосовних умов ви можете вимагати доступу, виправлення, видалення, обмеження обробки чи перенесення даних або заперечити проти обробки на підставі законного інтересу. Зверніться до вказаного вище оператора; на запити зазвичай відповідають протягом місяця, а будь-яке законне продовження пояснюється. Ви можете подати скаргу до наглядового органу, зокрема до угорського NAIH на naih.hu. Cook не використовує налаштування облікового запису для автоматизованих рішень із правовими чи подібними значущими наслідками.",
